"""Random registers, start positions and field widths.

Four builders in rotation keep the practice varied: a fully random field, a
field pinned to the low end, a lone bit anywhere, and the width = 32 case
that the mask formula has to special-case.
"""


def generate(rng, count):
    builders = (_anything, _low_field, _single_bit, _whole_register)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, reg, start, width, description=""):
    return {
        "name": name,
        "stdin": "%X %d %d\n" % (reg, start, width),
        "description": description,
    }


def _anything(rng, index):
    reg = rng.randrange(0, 2 ** 32)
    start = rng.randrange(32)
    width = rng.randint(1, 32 - start)
    return _case("a random field #%d" % index, reg, start, width,
                 "Bits %d..%d of a random register." %
                 (start, start + width - 1))


def _low_field(rng, index):
    reg = rng.randrange(0, 2 ** 32)
    width = rng.randint(1, 16)
    return _case("a field starting at bit 0 #%d" % index, reg, 0, width,
                 "start = 0 -- the shift is a no-op, only the mask matters.")


def _single_bit(rng, index):
    reg = rng.randrange(0, 2 ** 32)
    start = rng.randrange(32)
    return _case("a single bit #%d" % index, reg, start, 1,
                 "width = 1: the smallest possible field.")


def _whole_register(rng, index):
    reg = rng.randrange(0, 2 ** 32)
    return _case("the whole register #%d" % index, reg, 0, 32,
                 "width = 32 -- the case the mask formula has to "
                 "special-case.")
